using System.Text.Json;
using Zebex.Core;

int passed = 0;
void Check(string name, Action test) { test(); Console.WriteLine("PASS " + name); passed++; }
void Equal<T>(T expected, T actual) { if (!Equals(expected, actual)) throw new Exception($"Expected {expected}, got {actual}"); }
void Reject(Action action) { try { action(); } catch (ArgumentException) { return; } throw new Exception("Expected rejection"); }
Check("leading zeros and repeated scans", () => { var i = new Inventory(); i.Add(" 00123 ", 1); i.Add("00123", 2.5M); Equal(1, i.Scans.Count); Equal("00123", i.Scans[0].Code); Equal(3.5M, i.Scans[0].Quantity); });
Check("invalid scans leave inventory unchanged", () => { var i = new Inventory(); Reject(() => i.Add("", 1)); Reject(() => i.Add("abc\n123", 1)); Reject(() => i.Add("123", 0)); Reject(() => i.Add("123", -1)); Equal(0, i.Scans.Count); });
Check("CSV escaping and invariant quantities", () => { var i = new Inventory(); i.Add("A;\"B", 1.25M); Equal("Kod;Ilosc\r\n\"A;\"\"B\";1.25\r\n", i.Export(';', true)); });
Check("TSV with no header", () => { var i = new Inventory(); i.Add("001", 2); Equal("001\t2\r\n", i.Export('\t', false)); });
Check("session round trip", () => { var i = new Inventory(); i.Add("00042", 3.125M); var restored = JsonSerializer.Deserialize<List<Scan>>(JsonSerializer.Serialize(i.Scans))!; Equal(i.Scans[0], restored[0]); });
Check("remove and clear", () => { var i = new Inventory(); i.Add("1", 1); i.Add("2", 1); i.Remove("1"); Equal("2", i.Scans.Single().Code); i.Clear(); Equal(0, i.Scans.Count); });
Check("binary data including control bytes", () => { var bytes = WireBytes.ParseHex("02 00 ff\n03"); Equal("02 00 FF 03", WireBytes.Hex(bytes)); Equal((byte)0, bytes[1]); });
Check("reject malformed wire data", () => { Reject(() => WireBytes.ParseHex("F")); Reject(() => WireBytes.ParseHex("GG")); Reject(() => WireBytes.ParseHex(" ")); });
Check("Windows-allocated COM pair and reversed listing order", () => { var pairs = ComPairs.ParseList("  CNCB2 PortName=COM#,RealPortName=COM11,EmuBR=yes\r\n  CNCA2 PortName=COM#,RealPortName=COM10\r\n"); Equal(new ComPair(2, "COM10", "COM11"), pairs.Single()); });
Check("ignore unnamed, incomplete and invalid pairs", () => { var pairs = ComPairs.ParseList("CNCA0 PortName=CNCA0\nCNCB0 PortName=CNCB0\nCNCA1 PortName=COM3\nCNCA2 PortName=COM0\nCNCB2 PortName=COM4\nCNCA3 PortName=COM65536\nCNCB3 PortName=COM5\nCNCA4 PortName=COM8\nCNCB4 PortName=COM8"); Equal(0, pairs.Count); });
Check("select new pair without reusing other applications' ports", () => { var before = new[] { new ComPair(0, "COM3", "COM4") }; var expected = new ComPair(1, "COM5", "COM6"); Equal(expected, ComPairs.NewlyCreated(before, [before[0], expected])); });
Check("reject ambiguous installation result", () => { try { ComPairs.NewlyCreated([], [new(0, "COM3", "COM4"), new(1, "COM5", "COM6")]); } catch (InvalidOperationException) { return; } throw new Exception("Expected ambiguity rejection"); });
Check("official package hash check accepts exact data", () => { ArtifactIntegrity.Verify(System.Text.Encoding.ASCII.GetBytes("abc"), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"); });
Check("modified driver package is rejected", () => { try { ArtifactIntegrity.Verify(System.Text.Encoding.ASCII.GetBytes("abd"), "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"); } catch (InvalidDataException) { return; } throw new Exception("Expected integrity rejection"); });
Check("manual Skanuj keeps duplicate scans as separate rows", () => { var s = new CollectorSession(); var d = s.Open("Skanuj", ScanMode.Separate); d.Add("001", 2); d.Add("001", 3); Equal(2, d.Rows.Count); Equal(2M, d.Rows[0].Quantity); Equal(3M, d.Rows[1].Quantity); });
Check("manual Skanuj+ keeps zero totals until PC processing", () => { var s = new CollectorSession(); var d = s.Open("Skanuj+", ScanMode.Summed); d.Add("001", 2); d.Add("001", 3); d.Add("001", -5); Equal(1, d.Rows.Count); Equal(0M, d.Rows[0].Quantity); Equal("Kod;Ilosc\r\n001;0\r\n", d.Export(';')); });
Check("quick scans are always one and need no aggregation", () => { var d = new CollectorDocument("Szybki skan", ScanMode.Quick); d.Add("001", 99); d.Add("001", -99); Equal(2, d.Rows.Count); Equal(1M, d.Rows[0].Quantity); Equal(1M, d.Rows[1].Quantity); });
Check("separate document rejects negative corrections without mutation", () => { var d = new CollectorDocument("PZ", ScanMode.Separate); d.Add("001", 2); Reject(() => d.Add("001", -1)); Equal(2M, d.Rows.Single().Quantity); });
Check("documents are isolated and reopening continues scans", () => { var s = new CollectorSession(); s.Open("A", ScanMode.Summed).Add("001", 2); s.Open("B", ScanMode.Summed).Add("001", 3); s.Open("A", ScanMode.Summed).Add("001", 4); Equal(6M, s.Documents[0].Rows.Single().Quantity); Equal(3M, s.Documents[1].Rows.Single().Quantity); });
Check("loading catalog resets sums but preserves ordinary scans", () => { var s = new CollectorSession(); var plus = s.Open("Skanuj+", ScanMode.Summed); plus.Add("001", 4); var plain = s.Open("Skanuj", ScanMode.Separate); plain.Add("001", 7); s.LoadProducts([new("001", "Towar", 12, 9.99M)]); Equal(0M, plus.Rows.Single().Quantity); Equal(7M, plain.Rows.Single().Quantity); Equal("Towar", s.FindProduct("001")!.Name); });
Check("invalid catalog does not destroy sums or previous products", () => { var s = new CollectorSession(); s.LoadProducts([new("001", "Pierwotny", 1, 2)]); var d = s.Open("Skanuj+", ScanMode.Summed); d.Add("001", 5); Reject(() => s.LoadProducts([new("002", "A", 1, 1), new("002", "B", 1, 1)])); Equal(5M, d.Rows.Single().Quantity); Equal("Pierwotny", s.FindProduct("001")!.Name); });
Check("deleting products resets sums without deleting documents", () => { var s = new CollectorSession(); s.LoadProducts([new("001", "A", 1, 1)]); var d = s.Open("Skanuj+", ScanMode.Summed); d.Add("001", 5); s.DeleteProducts(); Equal(0, s.Products.Count); Equal(1, s.Documents.Count); Equal(0M, d.Rows.Single().Quantity); });
Check("manual send acknowledgement preserves document unless confirmed", () => { var s = new CollectorSession(); s.Open("A", ScanMode.Separate).Add("001", 2); s.ConfirmSimulatedSend("A", false); Equal(1, s.Documents.Count); s.ConfirmSimulatedSend("A", true); Equal(0, s.Documents.Count); });
Check("automatic and never-delete send policies", () => { var s = new CollectorSession { Deletion = DeleteAfterSending.Never }; s.Open("A", ScanMode.Separate).Add("001", 2); s.ConfirmSimulatedSend("A", true); Equal(1, s.Documents.Count); s.Deletion = DeleteAfterSending.Automatic; s.ConfirmSimulatedSend("A", false); Equal(0, s.Documents.Count); });
Check("session round trip preserves zero corrections, products and settings", () => { var s = new CollectorSession { Deletion = DeleteAfterSending.Never, Feedback = ScanFeedback.Data }; s.LoadProducts([new("001", "Nazwa", 12.5M, 9.99M)]); s.Open("A", ScanMode.Summed).Add("001", 2); s.Open("A", ScanMode.Summed).Add("001", -2); var restored = CollectorSession.FromJson(s.ToJson()); Equal(0M, restored.Documents.Single().Rows.Single().Quantity); Equal(9.99M, restored.FindProduct("001")!.Price); Equal(DeleteAfterSending.Never, restored.Deletion); Equal(ScanFeedback.Data, restored.Feedback); });
Check("legacy public version sessions remain readable", () => { var s = CollectorSession.FromJson("[{\"Code\":\"000123\",\"Quantity\":2.5}]"); Equal("000123", s.Documents.Single().Rows.Single().Code); Equal(2.5M, s.Documents.Single().Rows.Single().Quantity); });
Check("catalog CSV quoting, BOM and leading zeros", () => { var p = ProductCsv.Parse("\uFEFFKod;Nazwa;Stan;Cena\r\n000123;\"Towar; \"\"duży\"\"\";12.5;9.99\r\n").Single(); Equal("000123", p.Code); Equal("Towar; \"duży\"", p.Name); Equal(12.5M, p.Stock); Equal(9.99M, p.Price); });
Check("catalog rejects malformed columns, quotes and duplicate codes", () => { Reject(() => ProductCsv.Parse("Kod;Nazwa;Stan;Cena\n001;Towar;zle;1")); Reject(() => ProductCsv.Parse("Kod;Nazwa;Stan;Cena\n001;\"Towar;1;1")); Reject(() => ProductCsv.Parse("Kod;Nazwa;Stan;Cena\n001;A;1;1\n001;B;1;1")); });
Check("sum overflow leaves previously recorded quantity intact", () => { var d = new CollectorDocument("A", ScanMode.Summed); d.Add("001", decimal.MaxValue); try { d.Add("001", 1); } catch (OverflowException) { Equal(decimal.MaxValue, d.Rows.Single().Quantity); return; } throw new Exception("Expected overflow rejection"); });
Check("port parsing tolerates lowercase without losing endpoint association", () => { var pair = ComPairs.ParseList("cnca2 PortName=com10\ncncb2 PortName=com11").Single(); Equal(new ComPair(2, "COM10", "COM11"), pair); });
Console.WriteLine($"Completed: {passed} passed, 0 failed.");
